// Generated by esquadro: do not edit. Where the page shown is, for the
// header's breadcrumb: Home, a resource, one of its records (by its name),
// editing it.
import { isApiError } from "@api"
import { accountRealms } from "../accounts.gen.ts"
import { dashboards } from "../dashboard.gen.ts"
import { useQuery } from "@tanstack/react-query"
import { useMatches, useRouterState } from "@tanstack/react-router"
import { menu, isGroup } from "@/menu.ts"
import type { MenuItem } from "@/menu.ts"
import { base } from "../config.ts"
import { resources } from "../resources.gen.ts"
import { capitalize, t } from "./i18n.ts"
import type { Rec, ResourceMeta } from "./meta.ts"

export interface Crumb {
  label: string
  to?: string
}

/** The pages of the menu, with their groups' pages. */
function pages(): MenuItem[] {
  return menu.main.flatMap((e) => (isGroup(e) ? e.items : [e]))
}

// A page of yours names itself in the breadcrumb with its route's
// staticData: createFileRoute("/_app/settings")({ staticData: { title: "Settings" }, ... }).
declare module "@tanstack/react-router" {
  interface StaticDataRouteOption {
    title?: string
  }
}

function partsOf(pathname: string): string[] {
  const root = base.replace(/\/$/, "")
  const path = root && pathname.startsWith(root) ? pathname.slice(root.length) : pathname
  return path.split("/").filter(Boolean)
}

function metaOf(name: string | undefined): ResourceMeta | undefined {
  return Object.values(resources as unknown as Record<string, ResourceMeta>).find((r) => r.name === name)
}

/**
 * The breadcrumb of a path. A record is called by its name (record, once
 * its page has read it), or by its id until then; Not found, when missing.
 */
export function crumbsOf(pathname: string, title?: string, record?: Rec, missing = false, trash = false): Crumb[] {
  const parts = partsOf(pathname)
  const out: Crumb[] = [{ label: t("home"), to: "/" }]
  if (parts.length === 0) return out
  // A realm's accounts are called by its name.
  if (parts[0] === "accounts") {
    const r = accountRealms.find((x) => x.slug === parts[1])
    out.push({ label: t("administration") })
    if (parts[1]) out.push({ label: r?.label ?? capitalize(parts[1]), to: `/accounts/${parts[1]}` })
    return out
  }
  // A dashboard is called by the name the model gives it.
  if (parts[0] === "dashboards") {
    const d = dashboards.find((x) => x.slug === parts[1])
    out.push({ label: t("dashboards") })
    if (parts[1]) out.push({ label: d?.name ?? capitalize(parts[1]), to: `/dashboards/${parts[1]}` })
    return out
  }
  const meta = metaOf(parts[0])
  const page = pages().find((p) => p.to === `/${parts[0]}`)
  out.push({ label: meta?.label ?? page?.label ?? (parts.length === 1 && title ? title : parts[0]), to: `/${parts[0]}` })
  if (parts.length === 1 && trash && meta?.trash) out.push({ label: t("trash") })
  else if (parts[1] === "new") out.push({ label: t("new") })
  else if (parts[1]) {
    const name = meta && record ? String(record[meta.title] ?? "").trim() : ""
    // A record that is not there is not called by its id.
    out.push({ label: missing ? t("missing") : name || (meta ? parts[1] : capitalize(parts[1])), to: `/${parts[0]}/${parts[1]}` })
    if (parts[2] === "edit") out.push({ label: t("edit") })
  }
  return out
}

/** The breadcrumb of the page shown. */
export function useCrumbs(): Crumb[] {
  const pathname: string = useRouterState({ select: (s) => s.location.pathname })
  const trash = useRouterState({ select: (s) => Boolean((s.location.search as { trash?: unknown }).trash) })
  const title = useMatches({ select: (ms) => ms.map((m) => m.staticData?.title).filter(Boolean).pop() })
  const parts = partsOf(pathname)
  const meta = metaOf(parts[0])
  const id = meta && parts[1] && parts[1] !== "new" ? parts[1] : undefined
  // The record its page reads: the breadcrumb only looks in that query, it
  // never asks for it itself.
  const record = useQuery<Rec>({ queryKey: [meta?.name, "get", id], enabled: false })
  const missing = isApiError(record.error) && record.error.status === 404
  return crumbsOf(pathname, title, id ? record.data : undefined, missing, trash)
}
